import numpy as np
from PIL import Image
from scipy.ndimage import gaussian_filter
im=np.asarray(Image.open('/app/target.png').convert('RGB'),np.float32)/255
cols=np.array([[224,213,195],[219,183,161],[207,182,139],[167,176,177],[196,157,100],[175,147,124],[130,155,175],[165,142,101],[136,115,87],[103,112,114],[101,84,60],[53,74,90],[73,67,50],[56,60,61],[41,37,26],[36,27,15]],np.float32)/255
def lab(s):
 a=np.where(s<=.04045,s/12.92,((s+.055)/1.055)**2.4); M=np.array([[.4124564,.3575761,.1804375],[.2126729,.7151522,.072175],[.0193339,.119192,.9503041]]); xyz=a@M.T/np.array([.95047,1,1.08883]); f=np.where(xyz>(6/29)**3,np.cbrt(xyz),xyz/(3*(6/29)**2)+4/29); return np.stack([116*f[...,1]-16,500*(f[...,0]-f[...,1]),200*(f[...,1]-f[...,2])],-1)
ids=np.linalg.norm(gaussian_filter(lab(im),(4.5,4.5,0))[:,:,None]-lab(cols),axis=3).argmin(2)

def tracks(im, step=8, gap=12, minrun=6, phase=0):
 # union interval nodes on adjacent scan rows when same label intervals approach within gap
 parent=[]; lens=[]; rows=[]; intervals=[]; prev=[]; totalpix=0
 def find(x):
  while parent[x]!=x: parent[x]=parent[parent[x]]; x=parent[x]
  return x
 def union(a,b):
  a=find(a);b=find(b)
  if a!=b: parent[b]=a
 for y in range(phase,im.shape[0],step):
  row=im[y]; changes=np.r_[0,np.where(row[1:]!=row[:-1])[0]+1,im.shape[1]]
  cur=[]
  for a,b in zip(changes[:-1],changes[1:]):
   if b-a<minrun: continue
   nid=len(parent); parent.append(nid); lens.append(b-a); rows.append(y); interval=(int(a),int(b-1),int(row[a]),nid); cur.append(interval)
  for a,b,c,n in cur:
   for pa,pb,pc,pn in prev:
    if pc==c and max(pa-b,a-pb,0)<=gap: union(n,pn)
  prev=cur
 sizes={}; lengths={}
 for i,l in enumerate(lens):
  root=find(i); sizes[root]=sizes.get(root,0)+1; lengths[root]=lengths.get(root,0)+l
 return len(sizes),len(parent),sum(lens),sorted(lengths.values(),reverse=True)
for step in [6,8,10,12,14,16,20]:
 for minrun in [6,10,16,24]:
